export function createElementWithClassId(tag, classes, id) {
    const element = document.createElement(tag);
    if (classes) {
        element.classList.add(...classes);
    }
    if (id) {
        element.id = id;
    }
    return element;
}
export function textToUpperCase(text) {
    return text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();
}
export function createContainer(containerClass) {
    return createElementWithClassId('div', [
        'container',
        'flex',
        `${containerClass}-container`,
    ]);
}
export function createButtonsContainer(containerClass) {
    return createElementWithClassId('div', [
        'app__buttons-container',
        `app__buttons-container_${containerClass}`,
        'flex',
    ]);
}
export function getRandomIndex() {
    return Math.floor(Math.random() * 100);
}
export function enableButton(button) {
    button.disabled = false;
}
export function disableButton(button) {
    button.disabled = true;
}
export function getTrimmedInputValue(input) {
    return input.value.trim();
}
